-- Rifts World Book 13: Lone Star - its bestiary and its notable NPCs.
-- 11 creatures (migration 074) and 0 notable NPCs (migration 072),
-- with their attacks in stat_attacks (migration 073).
--
-- One-off data script, run once per environment. NOT a migration.
--
--   node scripts/d1-apply.mjs --local apps/character-creator/db/~099-lone-star-race-creatures.sql
--
-- Written by scripts/bestiary-sql.mjs from 2 worker file(s). Every
-- creature row passes creatureFormulaGaps, every value is printable ASCII,
-- and an 8-word shingle check of the prose fields against the book's cached text finds no copied run.



-- Read the result back. This script asserts its OWN rows and nothing else.
SELECT 'all 11 creatures are in' AS assertion, count(*) AS got, 11 AS want
  FROM creatures WHERE slug IN ('sea-dog', 'k-9-sniffer', 'kill-hound', 'ursa-warrior', 'battle-cat', 'kill-cat', 'mini-monkey-spy', 'monkey-boy-soldier', 'monkey-boy-tech', 'mutant-rat', 'mutant-bat');
SELECT 'and 11 of them are playable' AS assertion, count(*) AS got, 11 AS want
  FROM creatures WHERE playable = 1 AND slug IN ('sea-dog', 'k-9-sniffer', 'kill-hound', 'ursa-warrior', 'battle-cat', 'kill-cat', 'mini-monkey-spy', 'monkey-boy-soldier', 'monkey-boy-tech', 'mutant-rat', 'mutant-bat');
SELECT 'the creatures carry 39 attacks' AS assertion, count(*) AS got, 39 AS want
  FROM stat_attacks WHERE owner_kind = 'creature' AND owner_slug IN ('sea-dog', 'k-9-sniffer', 'kill-hound', 'ursa-warrior', 'battle-cat', 'kill-cat', 'mini-monkey-spy', 'monkey-boy-soldier', 'monkey-boy-tech', 'mutant-rat', 'mutant-bat');

