INSERT INTO creatures (slug, name, category, system, playable, alignment, attributes, hp, sdc, mdc, ppe, isp, pools_note, ar, horror_factor, combat, bonuses_note, skills_note, natural_abilities, magic, psionics, size, weight, life_span, habitat, allies, enemies, occ_note, description, source_book) VALUES
('sea-dog', 'Sea Dog', 'mutant', 'rifts', 1, 'Any, but most lean toward Principled, Scrupulous or Aberrant', '{"IQ":"3D6","ME":"3D6+4","MA":"3D6+6","PS":"3D6+6+1D4","PP":"3D6","PE":"3D6+6+1D4","PB":"3D6","Spd":"5D6"}', 'PE+10', '30', NULL, '3D6', '1D6x10+ME', 'Printed Newfoundland attributes are P.S. 3D6+6, P.E. 3D6+6 and Spd 3D6 (the same running or swimming; 1D6 digging); the formulas here add the Dog Boy physical bonuses the entry says apply on top: 1D4 P.S., +1D4 P.E. and +2D6 Spd. Hit Points are 10 plus the P.E. number and 1D6 per level. S.D.C. is 30 plus whatever physical skills add. I.S.P. is the M.E. number plus 1D6x10, +10 per additional level; regained at 2 per hour of activity or 12 per hour of meditation or sleep.', NULL, NULL, '{"initiative":2,"strike":1,"parry":1,"dodge":1}', '+2 to save vs disease, +2 vs possession, +1 vs psionic attack and +1 vs all forms of mind control. Half damage from cold. Combat as per Hand to Hand skill.', 'R.C.C. skills: speaks American and Spanish at 90%, Basic Math (+10%), Radio: Basic (+10%), Read Sensory Equipment (+10%), Paramedic (+15%), Pilot: Warships and Patrol Boats (+10%), Pilot: Water Scooters (+10%), Pilot: Water Skiing and Surfing, Advanced Fishing (+10%), Track & Hunt Sea Animals (+10%), S.C.U.B.A., Climbing, Land Navigation (+10%), Wilderness Survival (+10%), W.P. Energy Pistol, W.P. Energy Rifle, one W.P. of choice, Hand to Hand: Expert (Martial Arts for one other skill). Swims at 98%. Five other skills, +1 at levels 3, 6, 9 and 12; four secondary skills, +2 at levels 3, 6, 9 and 12. Never taught to read.', 'A born swimmer (98%) who holds its breath 1D4+2 minutes, shrugs off half of any cold damage and has oily, water-shedding fur. Sense Psychic and Magic Energy: 40% +5% per level, rolled each melee round and halved when several sources are scattered about; reaches 50 ft (15.2 m) +5 ft per added level for a psychic or mage holding powers in check, 400 ft (121 m) +50 ft per level once powers are in use; re-roll every 1000 ft (305 m) to keep the trail. Recognize Psychic Scent: 10% +4% per added level for a race or creature type (the page prints "10% 44%", a misprint), 8% +2% per added level for one known individual, +10% with hair, skin, blood or clothing worn in the last 4 hours, +10% on the trail of someone well known; reach 50 ft (15 m) +5 ft per level. Sense Supernatural Beings: name the type of creature, or spot possession, at 62% +2% per level; follow it at 35% +5% per level, or 70% +3% per level while it uses magic or psionics; reach 100 ft (30.5 m) per level for a quiet being, 1000 ft (305 m) +100 ft per added level for an active one. Smell and scent tracking run 20% under the Dog Boy figures, which are 70% +3% per level for common and strong scents (100 ft/30.5 m per level), 54% +2% per level for specific odors (25 ft/7.6 m per level) and 40% +4% per level to track by nose alone. Scent trails last up to four days (96 hours) unless washed out; roll every 1000 ft (305 m), half that on a faint or rained-on trail; two successes in three tries recover a lost trail. No tracking through water, and Astral Beings, ghosts and energy beings leave no smell. Odors carry through 12 inches (0.3 m) of earth or two feet (0.6 m) of snow. Blindness and total darkness cost only half the usual strike, parry and dodge penalties. Hearing reaches 35,000 vibrations a second (human 20,000). Field of vision 200 degrees for short-nosed breeds, 270 for long-nosed; colors slightly dull; no nightvision. Endurance is double a human''s: carries 20x P.S. in pounds (40x at P.S. 17 or more) and lifts twice that; two hours of hard steady effort or 40 minutes flat out before exhaustion (-2 Spd, -2 initiative, -2 damage, -1 strike, parry and dodge, doubling every further 15 minutes), cleared by about 15 minutes of rest. Ley lines and nexus points blot out the psychic and supernatural sensing (ordinary senses are untouched); Ley Line Storms bring headaches and static shocks and double the odds of being hit by ley line energy or lightning.', 'None', 'Counts as a master psionic (saves vs psionic attack on 10 or better). Automatic Sensitive powers: Sense Evil, Sense Magic, Sixth Sense and Empathy (receiving only), plus one more Sensitive power of choice.', '5 ft 9 inches to 6 ft 3 inches (1.7 to 1.82 m)', 'Around 190 lbs (85.5 kg), mostly muscle', '32-45 years; females 10 years more', 'Coalition Navy boats and bases, so far mostly the Great Lakes and the Gulf of Mexico', NULL, NULL, 'A full R.C.C. with its own skills; no O.C.C. is offered. Must be a Newfoundland or Newfoundland mix, and nine in ten of those are bred for the Navy. Outside CS service a player character is either a feral runaway or deserter, or the free-born child of runaways; the Coalition destroys both on sight. Standard issue is the Dog Boy kit plus a wet suit and diving gear.', 'The Coalition Navy''s Dog Boy, engineered from the web-footed Newfoundland: a thick-waisted, heavily built mutant with coarse oily fur in black, chocolate or black-marked white, webbed hands and feet and a bushy tail. Gentle, loyal and hard working, it serves in rescue, salvage, guard and combat duty afloat and warns its crew of unnatural storms and things from below.', 'Rifts World Book 13: Lone Star p.40-41'),
('k-9-sniffer', 'K-9 Sniffer', 'mutant', 'rifts', 1, 'Any, but most lean toward Principled, Scrupulous or Aberrant', '{"IQ":"3D6+2","ME":"3D6","MA":"3D6","PS":"3D6+1D4","PP":"3D6","PE":"3D6+4+1D4","PB":"3D6","Spd":"5D6"}', 'PE', '22', NULL, '4D6', '1D6x10+ME', 'Printed attributes are P.S. 3D6, P.E. 3D6+4 and Spd 3D6 running (1D6 digging); the formulas here add the Dog Boy physical bonuses the entry says apply on top: 1D4 P.S., +1D4 P.E. and +2D6 Spd. The R.C.C. requires I.Q. 10 or higher. Hit Points are the P.E. number and 1D6 per level. S.D.C. is 22 plus whatever physical skills add. I.S.P. is the M.E. number plus 1D6x10, +10 per additional level; regained at 2 per hour of activity or 12 per hour of meditation or sleep.', NULL, NULL, '{"initiative":2,"strike":1,"parry":1,"dodge":1}', '+2 to save vs disease, +2 vs possession, +1 vs psionic attack and +1 vs all forms of mind control. Tracking Bonus: +6% on the breed''s olfactory identification and tracking skills. Combat as per Hand to Hand skill.', 'R.C.C. skills: speaks American and Spanish at 90%, Basic Math (+15%), Radio: Basic (+10%), Read Sensory Equipment (+10%), Track (by sight/skill; +15%), Intelligence (+10%), Pilot Motorcycle/Hovercycle (+5%), Climbing, Running, Land Navigation (+20%), Wilderness Survival (+15%), W.P. Energy Pistol, W.P. Energy Rifle, one W.P. of choice, Hand to Hand: Expert (Martial Arts for one other skill). Five other skills, +1 at levels 3, 6, 9 and 12; six secondary skills, +2 at levels 3, 6, 9 and 12. Never taught to read.', 'Specialized Scent Training, two of five. Cancer: 70% +3% per level, -10% in bone and internal organs, at touch to one foot (0.3 m). Drugs: 77% +3% per level across four dozen or so substances, one roll to recognize and one to pinpoint or trail, -10% if concealed, nothing through an airtight container without outside residue, at touch to one foot per level. Explosives: 77% +3% per level, same rolls, penalty and reach as drugs. Robotics, bionics and implants: 80% +3% per level, tells a partial from a full conversion at once, -40% for bio-systems and organ replacements, -20% for symbiotes, parasites and androids, -10% per foot past the first. Sense Impending Natural Disasters: 70% +3% per level for storms, ley line storms, quakes and electromagnetic shifts up to 2D4 hours ahead (the optimum range line prints 1D6 hours) and 600 miles (960 km) off, timed to within 6D6 minutes (a miss is off by 3D6x10 minutes), -20% on an earthquake, +20% for ley line storms on or near a ley line, and it tells natural causes from magic or man-made ones. Sense Psychic and Magic Energy: 40% +5% per level, rolled each melee round and halved when several sources are scattered about; reaches 50 ft (15.2 m) +5 ft per added level for a psychic or mage holding powers in check, 400 ft (121 m) +50 ft per level once powers are in use; re-roll every 1000 ft (305 m) to keep the trail. Recognize Psychic Scent: 10% +4% per added level for a race or creature type (the page prints "10% 44%", a misprint), 8% +2% per added level for one known individual, +10% with hair, skin, blood or clothing worn in the last 4 hours, +10% on the trail of someone well known; reach 50 ft (15 m) +5 ft per level. Sense Supernatural Beings: name the type of creature, or spot possession, at 62% +2% per level; follow it at 35% +5% per level, or 70% +3% per level while it uses magic or psionics; reach 100 ft (30.5 m) per level for a quiet being, 1000 ft (305 m) +100 ft per added level for an active one. Smell, each figure +6% for the Sniffer: 70% +3% per level for common and strong scents (100 ft/30.5 m per level), 54% +2% per level for specific odors (25 ft/7.6 m per level) and 40% +4% per level to track by nose alone. Scent trails last up to four days (96 hours) unless washed out; roll every 1000 ft (305 m), half that on a faint or rained-on trail; two successes in three tries recover a lost trail. No tracking through water, and Astral Beings, ghosts and energy beings leave no smell. Odors carry through 12 inches (0.3 m) of earth or two feet (0.6 m) of snow. Blindness and total darkness cost only half the usual strike, parry and dodge penalties. Hearing reaches 35,000 vibrations a second (human 20,000). Field of vision 200 degrees for short-nosed breeds, 270 for long-nosed; colors slightly dull; no nightvision. Endurance is double a human''s: carries 20x P.S. in pounds (40x at P.S. 17 or more) and lifts twice that; two hours of hard steady effort or 40 minutes flat out before exhaustion (-2 Spd, -2 initiative, -2 damage, -1 strike, parry and dodge, doubling every further 15 minutes), cleared by about 15 minutes of rest. Ley lines and nexus points blot out the psychic and supernatural sensing (ordinary senses are untouched); Ley Line Storms bring headaches and static shocks and double the odds of being hit by ley line energy or lightning.', 'None', 'Counts as a master psionic (saves vs psionic attack on 10 or better). Automatic Sensitive powers: Sense Evil, Sense Magic, Sixth Sense and Empathy (receiving only), plus one more Sensitive power of choice.', '5 ft to 6 ft 6 inches (1.5 to 1.95 m)', 'Around 150 lbs (67.5 kg)', '32-45 years; females 10 years more', 'Trained at the Cabot & Dog Boy Training Grounds, the Lone Star Complex and Chi-Town; posted wherever the CS needs searches and manhunts', NULL, NULL, 'A full R.C.C. with its own skills; no O.C.C. is offered. Needs I.Q. 10 or better and a keen-nosed breed: German Shepherd, Basenji, Beagle, Bloodhound, Wolfhound, Elkhound, other hounds and mixes. Outside CS service a player character is either a feral runaway or deserter, or the free-born child of runaways; the Coalition destroys both on sight. Standard issue and pay are the Dog Boy''s.', 'K-9 Agents are Dog Boys picked for nose, stamina and brains and schooled to find explosives, drugs, hidden bionics and even tumors as well as the usual magic and monsters. Tall, lean, long-muzzled hounds with short coarse fur in tans, blacks and greys, they are patient team workers and relentless manhunters.', 'Rifts World Book 13: Lone Star p.41-43'),
('kill-hound', 'Kill Hound', 'mutant', 'rifts', 1, 'Any, but most lean toward Unprincipled (20%), Anarchist (22%), Aberrant (20%), Miscreant (20%) or Diabolic (13%); 5% other', '{"IQ":"2D6+3","ME":"3D6+6","MA":"2D6","PS":"4D6+12","PP":"3D6+6","PE":"4D6+4","PB":"3D6","Spd":"3D6+12"}', 'PEx2', '44', NULL, '2D6', '1D6x10+ME', 'Attributes, bonuses and stats replace the Dog Boy''s (no Dog Boy attribute bonuses are added). Spd is running; digging is 2D4. The R.C.C. requires I.Q. 5 and P.S. 20 or higher. Hit Points are the P.E. number x2 and 1D6 per level. S.D.C. is 44 plus whatever physical skills add. I.S.P. is the M.E. number plus 1D6x10, +10 per additional level; regained at 2 per hour of activity or 12 per hour of meditation or sleep.', NULL, NULL, '{"initiative":5,"strike":2}', 'Kill Hound Bonuses replace the Dog Boy physical bonuses: +5 initiative, +2 strike, +2 to save vs disease and poison, +2 vs possession, +10 vs Horror Factor. Supernatural endurance adds +3 to save vs poison, drugs and disease. Psi-bonus: +1 vs psionic attack and all forms of mind control. Berserker Rage and Rage Syndrome each give one extra melee attack and +6 damage while they last; after a Rage Syndrome seizure combat bonuses are halved and attacks reduced by one for 1D6x10 minutes. Combat as per Hand to Hand skill.', 'R.C.C. skills: speaks American and Spanish at 85%, Radio: Basic (+10%), Track Humanoids (by sight/skill; +15%), Track Animals (by sight/skill; +10%), Escape Artist (+5%), Pilot Motorcycle/Hovercycle (+5%), Climbing, Running, Boxing, Land Navigation (+10%), Wilderness Survival (+20%), W.P. Energy Pistol, W.P. Energy Rifle, W.P. Knife or Sword (vibro-blades), two W.P.s of choice, Hand to Hand: Martial Arts or Assassin. Four other skills, +1 at levels 4, 8 and 12; four secondary skills, +1 at levels 3, 6, 9 and 12. Never taught to read.', 'Leaps 15 ft (the page prints 3.6 m) up or along from a standstill and 30 ft (9 m) with a run. Hauls 100x its P.S. and stays active six hours before tiring. Every scent and scent-tracking figure is halved; it hunts by sight and skill as much as by nose. Behavioral problems: fights on through pain without penalty down to one hit point; shirks any dull duty and forgets details; brawls over slights and cannot refuse a challenge; a bloodlust that shuts out orders until the target is dead or the Hound is dragged off; a blind Berserker Rage against a hated foe that ends only with a death or a knockout. Rage Syndrome (01-20 on percentile): seizures foretold by glazed eyes, striking 1D4 minutes later and running 2D4 minutes in peace or 4D4 in combat. Jekyll and Hyde Syndrome (01-33 on percentile): abrupt swings from genial to surly. Sense Psychic and Magic Energy: 40% +5% per level, rolled each melee round and halved when several sources are scattered about; reaches 50 ft (15.2 m) +5 ft per added level for a psychic or mage holding powers in check, 400 ft (121 m) +50 ft per level once powers are in use; re-roll every 1000 ft (305 m) to keep the trail. Recognize Psychic Scent: 10% +4% per added level for a race or creature type (the page prints "10% 44%", a misprint), 8% +2% per added level for one known individual, +10% with hair, skin, blood or clothing worn in the last 4 hours, +10% on the trail of someone well known; reach 50 ft (15 m) +5 ft per level. Sense Supernatural Beings: name the type of creature, or spot possession, at 62% +2% per level; follow it at 35% +5% per level, or 70% +3% per level while it uses magic or psionics; reach 100 ft (30.5 m) per level for a quiet being, 1000 ft (305 m) +100 ft per added level for an active one. Smell, each figure halved for the Kill Hound: Dog Boys have 70% +3% per level for common and strong scents (100 ft/30.5 m per level), 54% +2% per level for specific odors (25 ft/7.6 m per level) and 40% +4% per level to track by nose alone. Scent trails last up to four days (96 hours) unless washed out; roll every 1000 ft (305 m), half that on a faint or rained-on trail; two successes in three tries recover a lost trail. No tracking through water, and Astral Beings, ghosts and energy beings leave no smell. Odors carry through 12 inches (0.3 m) of earth or two feet (0.6 m) of snow. Blindness and total darkness cost only half the usual strike, parry and dodge penalties. Hearing reaches 35,000 vibrations a second (human 20,000). Field of vision 200 degrees for short-nosed breeds, 270 for long-nosed; colors slightly dull; no nightvision. Ley lines and nexus points blot out the psychic and supernatural sensing (ordinary senses are untouched); Ley Line Storms bring headaches and static shocks and double the odds of being hit by ley line energy or lightning.', 'None', 'Counts as a master psionic (saves vs psionic attack on 10 or better). Automatic Sensitive powers: Sense Evil, Sense Magic, Sixth Sense and Empathy (receiving only), plus one more Sensitive power of choice.', '6-7 ft (1.8 to 2.1 m)', 'Around 200 lbs (90 kg)', 'An estimated 6-15 years; 97% die in combat', 'CS front lines and wilderness hunts, notably the siege on Tolkeen; trained at base Cabot, the Lone Star Complex and Chi-Town', NULL, NULL, 'A full R.C.C. with its own skills; no O.C.C. is offered. Needs I.Q. 5 and P.S. 20 or better; usual stock is wolf or a big breed such as the Akita, Rottweiler, Mastiff, Elkhound, Wolfhound, Bouvier Des Flandres or Rhodesian Ridgeback, and mixes of them. 90% are male. Outside CS service a player character is either a feral runaway or deserter, or the free-born child of runaways; the Coalition destroys both on sight. All carry three implants (toxic filter, clock calendar, gyro-compass) and pick one more from the common list; usually issued heavy DPM or full environmental armor.', 'A GED design first fielded in 104 P.A.: a huge, barrel-chested, shaggy mutant canine bred to be fearless shock infantry and a hunter-killer of D-bees, mages and monsters. Kill Hounds keep their predatory edge, run in packs with an alpha and a beta, obey their human masters grudgingly and never pass up a hunt.', 'Rifts World Book 13: Lone Star p.43-45'),
('ursa-warrior', 'Ursa-Warrior', 'mutant', 'rifts', 1, 'Any, but most (65%) lean toward Anarchist and Miscreant', '{"IQ":"2D6","ME":"2D6","MA":"2D6","PS":"5D6","PP":"3D6","PE":"4D6","PB":"2D6","Spd":"4D6"}', 'PEx5', 'PE+2D4x10', NULL, '3D6', 'MEx2', 'Standard attributes before the species bonuses in the bonuses note. Spd is running; digging is 2D4. Hit Points are the P.E. number x5 plus 2D6 per level; S.D.C. is the P.E. number plus 2D4x10 plus whatever physical skills add; some species add to both. Natural Armor Rating is 10+1D6, a roll, so the ar column is empty: an attack must roll above it to do Hit Point/S.D.C. damage, and mega-damage weapons ignore it. I.S.P. is double the M.E. number, +2D4 per additional level; regained at 2 per hour of activity or 8 per hour of meditation or sleep. P.S. and P.E. are always supernatural and most attacks do mega-damage.', NULL, NULL, NULL, '+1 to save vs psionic attack and all forms of mind control. By species, on top of the standard attributes. Black Bear: +1 initiative, +1 strike and parry, +3 vs disease, +3 vs Horror Factor; I.Q. +1D4, M.A. +1D6, P.P. +1D6, Spd +3D6; size -20%; nightvision 200 ft (61 m); +20% climb. Brown Bear: +3 initiative, +2 strike and parry, +4 vs disease, +6 vs Horror Factor, +5D6 Hit Points, +1D6x10 S.D.C.; size +30%; I.Q. +1, P.S. +2D6, P.E. +1D6, Spd +2D6; natural wrestler. Grizzly Bear: +2 initiative, +3 strike, +2 parry, +1 attack per melee, +4 vs disease, +8 vs Horror Factor, +1D6x10 Hit Points, +2D4x10 S.D.C.; size +40%; P.S. +3D6, P.E. +2D6; +10% swimming, -10% climbing. Polar Bear: +3 initiative, +4 strike, +1 parry and dodge, +1 attack per melee, +4 vs disease, +7 vs Horror Factor, +1D4x10 Hit Points, +1D6x10 S.D.C.; size +25%; I.Q. +1D6, P.S. +3D6, P.E. +2D6, Spd +2D6; swims at 96%, holds breath six minutes, dives 20 ft (6 m), half damage from cold. Combat as per Hand to Hand skill.', 'R.C.C. skills: speaks American at 80%, Radio: Basic (+10%), Running, Land Navigation (+10%), Wilderness Survival (+15%), W.P. Energy Pistol, W.P. Energy Rifle, W.P. Heavy Energy, one W.P. of choice, Hand to Hand: Expert. Climbs at 60%/40% and swims at 50% before species bonuses. Four other skills, +1 at levels 4, 8 and 12; four secondary skills, +1 at levels 2, 4, 8 and 12. Never taught to read.', 'Sense Psychic and Magic Energy at 20% +5% per level (halved for scattered sources): 20 ft (the page prints 12 m) +5 ft per added level for a psychic or mage at rest, 200 ft (61 m) +20 ft per level for powers in use, re-rolled every 400 ft (122 m); no recognition of psychic scents. Sense Supernatural Beings: name the creature type or spot possession at 40% +2% per level; follow it at 15% +5% per level, or 53% +3% per level while it uses magic or psionics; reach 100 ft (30.5 m) per level for a quiet being, 1000 ft (305 m) +100 ft per added level for an active one. Smell is a third to half a Dog Boy''s yet ten times human: common and strong scents 43% +3% per level (100 ft/30.5 m per level), specific odors 26% +2% per level (25 ft/7.6 m per level), tracking by nose alone 20% +4% per level with half the usual blindness penalties, rolled every 500 ft (152 m) on trails up to a day old; no tracking through water. Hearing slightly above human, 200 degree vision, night sight about 30% better than human. Sprints at double Spd for 1D4 minutes. Ley lines and nexus points wipe out the psychic sensing and bring a headache, and Ley Line Storms hit it as they do Dog Boys.', 'None', 'Counts as a major psionic (saves vs psionic attack on 12 or better). Two powers of choice from the Physical category.', '7 feet (2.1 m)', '700-900 pounds', 'Estimated 30-45 years', 'CS Dog Packs in the State of Lone Star (about one bear per squad of ten) and special Dog Packs in the Tolkeen campaign', NULL, NULL, 'A full R.C.C. with its own skills; no O.C.C. is offered. Pick a species: Black, Brown, Grizzly or Polar Bear. 80% are female. The Dog Boy optional tables are closed to bears, though the G.M. may allow the Mutation Gone Wrong Table. Outside CS service a player character is either a feral runaway or deserter, or the free-born child of runaways; the Coalition destroys both on sight. Issued a large 50 M.D.C. DPM riot suit (no environmental armor) and paid a token 60-100 credits a month; rank tops out at Sergeant.', 'An experimental mutant bear fielded with CS Dog Packs for raw strength and as a pack mule: bear-headed, fur covered, short-legged and long-armed, with stubby clawed fingers, and inclined to run on all fours. Most think and feel like a child of seven to ten, take their mood from the squad around them and can tip into a berserk frenzy when comrades fall or they are cornered.', 'Rifts World Book 13: Lone Star p.72-75'),
('battle-cat', 'Battle Cat', 'mutant', 'rifts', 1, 'Any, but 35% lean toward Anarchist and 25% toward Aberrant', '{"IQ":"3D6","ME":"3D6","MA":"4D6","PS":"4D6","PP":"4D6","PE":"4D6","PB":"4D6","Spd":"4D6+6"}', 'PEx2', 'PE+1D4x10', NULL, '3D6', 'MEx2', 'Standard attributes before the species bonuses in the bonuses note. Spd is running; reduce it 10% when climbing. Hit Points are the P.E. number x2 plus 2D6 per level; S.D.C. is the P.E. number plus 1D4x10 plus whatever physical skills add; some species add to both. Natural Armor Rating is 9+1D4, a roll, so the ar column is empty: an attack must roll above it to do Hit Point/S.D.C. damage, and mega-damage weapons ignore it. I.S.P. is double the M.E. number, +2D6 per additional level; regained at 2 per hour of activity or 8 per hour of meditation or sleep. The P.S. and P.E. of African Lions and Tigers can be made supernatural.', NULL, NULL, NULL, '+2 to save vs psionic attack and all forms of mind control. Species bonuses, cumulative with skills. Lynx/Bobcat: +3 initiative, +1 strike and parry, +3 dodge, +2 vs disease, +4 vs Horror Factor; P.P. +1D4, Spd +1D6; leap 20 ft (6 m) across or 15 ft up (page prints 6 m); size -20%; +20% climb, +10% acrobatics. Puma/Cougar/Mountain Lion: +2 initiative, +2 strike and parry, +2 vs disease, +5 vs Horror Factor, +4D6 Hit Points, +5D6 S.D.C.; I.Q. +1D4, P.S. +1D6; leap 40 ft (12 m) across or 20 ft (6 m) up; +10% prowl, climb and swim. Leopard/Panther: +4 initiative, +3 strike, +1 parry, +3 dodge, +1 attack per melee, +3 roll with impact, +1 vs disease, +3 vs Horror Factor, +3D6 Hit Points, +4D6 S.D.C.; I.Q. +1D4, P.S. +3D6, P.P. +1D4; leap 30 ft (9 m) across or 20 ft (6 m) up, +20% with a running start; +15% prowl, +10% acrobatics, +30 climb. Snow Leopard: as the leopard, plus size +20%, a further +1D6 Hit Points, +2D6 S.D.C. and +1D6 P.S.; leap 50 ft (15.2 m) across and 20 ft (6 m) high. African Lion: +2 initiative, +2 strike, +3 parry, +1 attack per melee, +4 vs disease, +6 vs Horror Factor, +6D6 Hit Points, +1D6x10 S.D.C.; size +40% (typically 7 ft/2.1 m); P.S. +3D6, P.E. +1D6, Spd +2D6; leap 20 ft (6 m) across or 15 ft (4.6 m) up; roar heard a mile (1.6 km) off; +10% swim, +10% prowl, +5% climbing, +10% tracking skills. Tiger: +4 initiative, +3 strike, +2 parry, +1 attack per melee, +4 vs disease, +6 vs Horror Factor, +1D4x10 Hit Points, +2D4x10 S.D.C.; size +60% (typically 8 ft/2.4 m); I.Q. +1D4, P.S. +4D6, P.E. +2D6, Spd +1D6; leap 30 ft (9 m) across or 15 ft (4.6 m) up; roar heard 1.5 miles (2 km) off; swims at 86%; +5% climbing, +15% prowl, +15% tracking skills; Siberian tigers take half damage from cold. Combat as per Hand to Hand skill, or by weapon.', 'R.C.C. skills: speaks American at 90%, Basic Math, Radio: Basic (+10%), Acrobatics, Climbing, Running, Prowl, Track Animals (+10%), Track Humanoids (+10%), Land Navigation (+20%), Wilderness Survival (+15%), W.P. Knife (Vibro-Blade), W.P. Energy Rifle, one W.P. of choice, Hand to Hand: Expert or Assassin. Four other skills, +1 at levels 3, 6, 9 and 12; six secondary skills, +2 at levels 2, 4, 8 and 11. Never taught to read.', 'Sense Psychic and Magic Energy at 30% +5% per level (halved for scattered sources): 40 ft (12 m) +5 ft per added level for a psychic or mage at rest, 300 ft (91 m) +20 ft per level for powers in use, re-rolled every 400 ft (122 m). No recognition of psychic scents. Sense Supernatural Beings: name the creature type or spot possession at 54% +2% per level; follow it at 10% +2% per level, or 23% +3% per level while it uses magic or psionics; reach 100 ft (30.5 m) per level for a quiet being, 1000 ft (305 m) +100 ft per added level for an active one. Sight is the chief sense: 20/20 color vision across 220 degrees, and passive night sight 6-7 times a human''s that still needs some ambient light; in true darkness the cat is blind (-4 strike, parry and dodge) but gets about by smell, hearing and whiskers 2-3 times better than a human. Hearing reaches 25,000 vibrations a second, with roughly 30 ear muscles: place a sound source at 80% +2% per level, and name prey or a machine from its sound at 72% +2% per level (-20% for artificial sounds); both lose 10% per 50 yards (150 ft/45.7 m) of distance. Smell is about twice human (a tiger''s is merely human). Climbs at 60%/40% and swims at 50% before species bonuses (tigers 86%). Sprints at double Spd for 1D4 minutes. Ley lines and nexus points wipe out the psychic sensing and bring on a headache, though cats are spared the ley line storm effects that plague canines.', 'None in CS service. A feral or free-born cat may study magic, chiefly as a Shifter or Ley Line Walker and rarely Techno-Wizardry.', 'Counts as a major psionic (saves vs psionic attack on 12 or better). Two powers of choice from the Sensitive category.', '5 feet (1.5 m)', '200-300 pounds (90 to 135 kg)', 'Estimated 40-55 years', 'About 3,200 in CS service: half in the State of Lone Star, a third on the Tolkeen front, the rest in the wilderness of the American West', NULL, NULL, 'A full R.C.C. with its own skills. Pick a species: Lynx/Bobcat, Puma/Cougar/Mountain Lion, Leopard/Panther, Snow Leopard, African Lion or Tiger. A free-born cat that becomes a mage takes the skills of its magic O.C.C. (Shifter or Ley Line Walker, rarely Techno-Wizard) in place of most of this R.C.C.''s, keeping its natural abilities. 60% are female. The Dog Boy optional tables are closed to cats, though the G.M. may allow the Mutation Gone Wrong Table. Outside CS service a player character is either a feral runaway or deserter, or the free-born child of runaways; the Coalition destroys both on sight. Paid a token 90-130 credits a month; rank tops out at Sergeant Major.', 'A mutant feline soldier of the Coalition: cat-headed and furred with a tail, usually on human legs, slender but powerful, with thick fingers and retractable claws. Reserved, blunt and independent, these cats do poorly at drudge or garrison work and best alone or in teams of two to ten on reconnaissance, espionage and seek and destroy assignments in the wild.', 'Rifts World Book 13: Lone Star p.76-79'),
('kill-cat', 'Kill Cat', 'mutant', 'rifts', 1, 'Any, but 25% lean toward Anarchist, 25% Aberrant and 20% Miscreant', '{"IQ":"3D6","ME":"3D6","MA":"3D6","PS":"4D6+6","PP":"4D6","PE":"4D6","PB":"3D6","Spd":"4D6+6"}', 'PEx3', 'PE+1D6x10', NULL, '2D6', 'MEx2', 'Standard attributes before the Battle Cat species bonuses in the bonuses note. Spd is running; reduce it 20% when climbing. Hit Points are the P.E. number x3 plus 2D6 per level; S.D.C. is the P.E. number plus 1D6x10 plus whatever physical skills add; some species add to both. Natural Armor Rating is 9+1D6, a roll, so the ar column is empty: an attack must roll above it to do Hit Point/S.D.C. damage, and mega-damage weapons ignore it. I.S.P. as the Battle Cat: double the M.E. number, +2D6 per additional level. 33% have supernatural P.S. and P.E.', NULL, NULL, NULL, '+2 to save vs psionic attack and all forms of mind control. About half suffer one or two of the Kill Hound''s aggression problems. Species bonuses, cumulative with skills. Lynx/Bobcat: +3 initiative, +1 strike and parry, +3 dodge, +2 vs disease, +4 vs Horror Factor; P.P. +1D4, Spd +1D6; leap 20 ft (6 m) across or 15 ft up (page prints 6 m); size -20%; +20% climb, +10% acrobatics. Puma/Cougar/Mountain Lion: +2 initiative, +2 strike and parry, +2 vs disease, +5 vs Horror Factor, +4D6 Hit Points, +5D6 S.D.C.; I.Q. +1D4, P.S. +1D6; leap 40 ft (12 m) across or 20 ft (6 m) up; +10% prowl, climb and swim. Leopard/Panther: +4 initiative, +3 strike, +1 parry, +3 dodge, +1 attack per melee, +3 roll with impact, +1 vs disease, +3 vs Horror Factor, +3D6 Hit Points, +4D6 S.D.C.; I.Q. +1D4, P.S. +3D6, P.P. +1D4; leap 30 ft (9 m) across or 20 ft (6 m) up, +20% with a running start; +15% prowl, +10% acrobatics, +30 climb. Snow Leopard: as the leopard, plus size +20%, a further +1D6 Hit Points, +2D6 S.D.C. and +1D6 P.S.; leap 50 ft (15.2 m) across and 20 ft (6 m) high. African Lion: +2 initiative, +2 strike, +3 parry, +1 attack per melee, +4 vs disease, +6 vs Horror Factor, +6D6 Hit Points, +1D6x10 S.D.C.; size +40% (typically 7 ft/2.1 m); P.S. +3D6, P.E. +1D6, Spd +2D6; leap 20 ft (6 m) across or 15 ft (4.6 m) up; roar heard a mile (1.6 km) off; +10% swim, +10% prowl, +5% climbing, +10% tracking skills. Tiger: +4 initiative, +3 strike, +2 parry, +1 attack per melee, +4 vs disease, +6 vs Horror Factor, +1D4x10 Hit Points, +2D4x10 S.D.C.; size +60% (typically 8 ft/2.4 m); I.Q. +1D4, P.S. +4D6, P.E. +2D6, Spd +1D6; leap 30 ft (9 m) across or 15 ft (4.6 m) up; roar heard 1.5 miles (2 km) off; swims at 86%; +5% climbing, +15% prowl, +15% tracking skills; Siberian tigers take half damage from cold. Combat as per Hand to Hand skill, or by weapon.', 'R.C.C. skills: speaks American at 90%, Basic Math, Radio: Basic (+10%), Climbing, Running, Prowl, Intelligence (+10%), Escape Artist (+10%), Track Humanoids (+10%), Land Navigation (+20%), Wilderness Survival (+20%), Trap Construction (+14%), Sniper, W.P. Knife (Vibro-Blade), W.P. Energy Rifle, one W.P. of choice, Hand to Hand: Martial Arts or Assassin. Three other skills, +1 at levels 3, 6, 9 and 12; four secondary skills, +2 at levels 2, 4, 8 and 11. Never taught to read.', 'The Battle Cat''s abilities throughout. Sense Psychic and Magic Energy at 30% +5% per level (halved for scattered sources): 40 ft (12 m) +5 ft per added level for a psychic or mage at rest, 300 ft (91 m) +20 ft per level for powers in use, re-rolled every 400 ft (122 m). No recognition of psychic scents. Sense Supernatural Beings: name the creature type or spot possession at 54% +2% per level; follow it at 10% +2% per level, or 23% +3% per level while it uses magic or psionics; reach 100 ft (30.5 m) per level for a quiet being, 1000 ft (305 m) +100 ft per added level for an active one. Sight is the chief sense: 20/20 color vision across 220 degrees, and passive night sight 6-7 times a human''s that still needs some ambient light; in true darkness the cat is blind (-4 strike, parry and dodge) but gets about by smell, hearing and whiskers 2-3 times better than a human. Hearing reaches 25,000 vibrations a second, with roughly 30 ear muscles: place a sound source at 80% +2% per level, and name prey or a machine from its sound at 72% +2% per level (-20% for artificial sounds); both lose 10% per 50 yards (150 ft/45.7 m) of distance. Smell is about twice human (a tiger''s is merely human). Climbs at 60%/40% and swims at 50% before species bonuses (tigers 86%). Sprints at double Spd for 1D4 minutes. Ley lines and nexus points wipe out the psychic sensing and bring on a headache, though cats are spared the ley line storm effects that plague canines.', 'None. Even feral and free-born Kill Cats avoid studying magic, though they may learn about magic weapons, charms and devices.', 'As the Battle Cat: counts as a major psionic (saves vs psionic attack on 12 or better), with two powers of choice from the Sensitive category.', '6 feet (1.8 m); the equipment entry gives 7 to 9 ft (2.1 to 2.7 m) as the average for these oversized cats', '500 pounds (the page prints 90 to 135 kg beside it)', 'Estimated 30-50 years', 'Assigned hunting grounds in the wilderness, shared with 2D6 other Kill Cats and worked alone, in pairs or in small groups; fewer than 600 are on active duty', NULL, NULL, 'A full R.C.C. with its own skills; no O.C.C. is offered. Usually a Snow Leopard, African Lion or Tiger, with species bonuses as listed for the Battle Cat. 70% are male. Outside CS service a player character is either a feral runaway or deserter, or the free-born child of runaways; the Coalition destroys both on sight. Issued 70 M.D.C. DPM riot style armor, with rail guns and heavy weapons available; paid a token 30-60 credits a month; rank tops out at Sergeant Major.', 'The big cats of the Coalition''s feline program, chosen for size and given the aggression of a Kill Hound. Each is turned loose on a stretch of wilderness with orders to kill any non-human not in CS service, living off the land for months and checking in by radio every two weeks.', 'Rifts World Book 13: Lone Star p.79-81'),
('mini-monkey-spy', 'Mini Monkey Spy', 'mutant', 'rifts', 1, 'Any, but 25% lean toward Unprincipled, 25% Anarchist and 25% Aberrant', '{"IQ":"7","ME":"3D6","MA":"3D6","PS":"1D6+4","PP":"3D6+6","PE":"2D6+8","PB":"3D6","Spd":"2D6+10"}', 'PE+1D4', 'PE+3D6', NULL, '4D6', NULL, 'Hit Points are the P.E. number plus 1D4 per level of experience (the formula is level one); larger species may roll 1D6 or 2D6 instead. S.D.C. is the P.E. number +3D6, or +5D6 for larger species. I.Q. is printed as an average of 7, not as dice. Spd is ground running; double it in trees. Armor Rating: not applicable.', NULL, NULL, '{"attacks":2,"initiative":2,"dodge":2,"roll":4}', 'Attacks/melee actions per round: 2 to start, +1 at levels 3, 6, 9 and 13. Hand to Hand: not applicable. Dodge is +2 on the ground or +4 in trees. With a gun: no bonuses and -5 to strike; a thrown grenade is -2 to strike at about 40 feet (12 m). Snow and ice: -20% to prowl, climb and acrobatics, speed and leaps cut by 30%. Full environmental armor (20 M.D.C.) cuts speed, leaps, prowl, climbing and acrobatics by 20%.', 'Natural: Swim 30%, Climb 95%/90%, Acrobatics 90%, Prowl 56% +2% per level, identify edible plants 80%. R.C.C. skills: understands American at 80% (speaks a few words), Radio: Basic (+10%), Optic Systems (+5%), TV/Video, Surveillance Systems and Tailing (+5%, no tracking), Pick Pockets (+5%), Land Navigation (+20%), Wilderness Survival (+15%), W.P. Knife (scalpel and laser scalpel). Three other skills, plus one at levels 3, 6, 9 and 12; one secondary skill at each of levels 1, 2, 4, 8, 10, 12 and 14. Never taught to read.', 'Grips with feet and tail alike. Jumps 5 feet (1.5 m) high and 10 feet across, half again as far lengthwise off a run or a swing, and can drop as much as 20 ft (6 m) down through branches. Moves through a tree canopy at twice its ground speed. Knows by instinct which plants a monkey can eat (80%). Understands 600+ spoken words and manages simple tools such as cameras, recorders and flashlights, but says a dozen words at most.', 'None', 'None', '2 feet (0.6 m) long, plus a tail of another 2-3 feet (0.6 to 0.9 m)', '5-10 pounds (2.3 to 4.5 kg)', 'Estimated 20-30 years', 'Coalition service: over 200 at Lone Star, 300 at Chi-Town, 60 at Tolkeen and a hundred or more at Free Quebec. At its best in cities with tall buildings and in forest or jungle; does poorly in long freezing winters', 'The Coalition States, which made and trained it', 'Ordinary cats, dogs and other predators; a runaway is destroyed by the Coalition if met, though seldom hunted', 'A full R.C.C. with its own skills; no O.C.C. is offered. The book calls it playable but better as a G.M.''s NPC, and most do not pass 8th level. A character outside Coalition service is a runaway or a runaway''s offspring. Typical kit: custom light armor (11 M.D.C.), a scalpel, a laser scalpel, two flares, small binoculars, a small radio and a pen flashlight. No money of its own, generally no cybernetics, and it cannot drive a vehicle.', 'A squirrel-sized monkey whose mind alone was raised, to roughly low human level, while body, tail and instincts were left as nature made them. The Coalition uses it to watch, tail, steal and plant bugs in places nothing larger can reach. It is a plant eater and no fighter.', 'Rifts World Book 13: Lone Star p.81-83'),
('monkey-boy-soldier', 'Monkey Boy Soldier', 'mutant', 'rifts', 1, 'Any', '{"IQ":"2D6+7","ME":"3D6","MA":"2D6+8","PS":"4D6+10","PP":"2D6+6","PE":"2D6+8","PB":"2D6+2","Spd":"2D6+6"}', 'PE+1D6', 'PEx2', NULL, '6D6', NULL, 'The formulas are the chimpanzee and orangutan figures: Hit Points are the P.E. number plus 1D6 per level of experience (level one shown) and S.D.C. is P.E. x2. A gorilla has Hit Points of P.E. x2 plus 2D6 per level and S.D.C. of the P.E. number +2D4x10, and gorilla test subjects are often given supernatural P.S. and P.E. Armor Rating applies to gorillas only and is rolled, 1D4+5, so the A.R. column is left empty. I.S.P. is not printed.', NULL, NULL, '{"initiative":2,"dodge":2,"roll":3}', '+1 attack per melee round on top of the Hand to Hand skill. The +2 dodge holds on the ground or in trees and does not apply to gorillas. Combat by Hand to Hand: Expert or Assassin, whichever the CS wants. No natural attack damage is printed.', 'Natural: Climb 75%/65% (-20% for gorillas), Gymnastics 60% (-10% for gorillas), identify edible plants 70%. R.C.C. skills: speaks American at 90%, Basic Math (+20%), Radio: Basic (+10%), Radio: Scrambler (+10%), Military Etiquette (+10%), Escape Artist (+10%), Intelligence (+10%), W.P. Pistol, W.P. Energy Rifle, one W.P. of choice, Hand to Hand: Expert or Assassin. Four other skills, plus two at levels 3, 6, 9 and 12; four secondary skills, plus two at levels 2, 4, 8, 10, 12 and 14. In CS service never taught to read, pilot, or learn mechanical, science, tracking or wilderness survival skills.', 'Smells half again as well as a human. Jumps 4 feet (1.2 m) high and 8 feet (2.4 m) across, a fifth farther lengthwise off a run or a swing. Travels through trees at about its running speed (the printed sentence is garbled and may mean double); a gorilla manages about half. Feet that grip, no tail, double jointed. Knows which plants an ape can eat (70%). Speech is very good, often close to human.', 'None. Feral and free-born chimpanzees may study any mystic art; such a mage drops this R.C.C.''s skills for those of the magic O.C.C. and keeps the natural abilities', 'Roughly the same as humans', '3-4 feet (0.9 to 1.2 m) unaltered, 5-6 feet (1.5 to 1.8 m) with genetic alteration. Gorillas: 5.6 to 5.9 feet (1.65 to 1.7 m), up to 6 feet 6 inches (1.95 m) fully erect; 7-12 feet (2.1 to 3.6 m) with alteration, up to 15 ft (4.6 m) erect', 'Chimpanzees 70-90 pounds (31.7 to 40.8 kg); orangutans 90 to 140 pounds (40.8 to 63 kg); gorillas 200 to 300 pounds (90 to 135 kg), up to half a ton for giant sizes. Typically doubled for genetically altered, more human-like apes', 'Estimated 40-55 years', 'The Lone Star Complex and CS Army units; chimpanzees are 95% of all Monkey Boys', 'The Coalition States; some serve in Dog Packs', 'A Monkey Boy that deserts or goes feral is hunted down and killed by the Coalition', 'A full R.C.C. with its own skills. A free-born chimpanzee mage may instead take the skills of a magic O.C.C. A character outside CS service is a deserter or the free-born offspring of runaways; free-borns and runaways may add pilot, rogue and wilderness skills as secondary skills. Kit is DPM riot armor, an energy rifle and energy pistol with either a Neuro-Mace or a Vibro-Blade; pay is 60-100 credits a month. Cybernetics: generally none at first, but 10% carry 1-4 bionic additions, 5% are M.O.M.-implant Crazies and 2% are partial Borgs. Rank stops at Sergeant Major.', 'A chimpanzee, orangutan or gorilla raised to human intelligence and, for chimps and orangs, often given a larger, more upright body. Bred as Coalition infantry, they are clever, curious and hard to control, and the army keeps them on dull duties under close watch.', 'Rifts World Book 13: Lone Star p.83-84'),
('monkey-boy-tech', 'Monkey Boy Tech', 'mutant', 'rifts', 1, 'Any', '{"IQ":"2D6+1D6+8","ME":"3D6+1D4","MA":"2D6+1D4+8","PS":"4D6+10","PP":"2D6+6","PE":"2D6+8","PB":"2D6+2","Spd":"2D6+6"}', 'PE+1D6', 'PEx2', NULL, '6D6', NULL, 'The entry prints only its changes to the Monkey Boy Soldier (printed 83-84), so every pool is that entry''s chimpanzee figure: Hit Points are the P.E. number plus 1D6 per level of experience (level one shown), S.D.C. is P.E. x2, P.P.E. 6D6. The attribute formulas are the Soldier''s dice with the Tech''s printed bonuses folded in: I.Q. +1D6+1, M.E. +1D4, M.A. +1D4. Armor Rating: none (gorillas only, and a Tech is a chimpanzee). I.S.P. is not printed.', NULL, NULL, '{"initiative":2,"dodge":2,"roll":3}', 'The Soldier''s natural bonuses, by reference: +1 attack per melee round on top of the Hand to Hand skill, and the +2 dodge holds on the ground or in trees. Combat by Hand to Hand: Basic; no other style is available. No natural attack damage is printed.', 'Natural (as the Soldier): Climb 75%/65%, Gymnastics 60%, identify edible plants 70%. R.C.C. skills: speaks and is literate in American at 98%, one more spoken language (+20%), Basic Math (+30%), Advanced Math (+20%), Radio: Basic (+10%), three Medical or four Mechanical skills of choice, two Electrical skills of choice, Biology (+20%), Chemistry (+20%), one W.P. of choice, Hand to Hand: Basic. Five other skills, plus one at levels 3, 6, 9 and 12; five secondary skills, plus two at levels 2, 4, 8, 10, 12 and 14. No Pilot, Pilot Related or Wilderness skills.', 'As the Monkey Boy Soldier''s chimpanzee: smells half again as well as a human, jumps 4 feet (1.2 m) high and 8 feet (2.4 m) across (a fifth farther off a run or swing), moves through trees at about its running speed, has gripping feet and no tail, is double jointed, and knows which plants an ape can eat (70%). Speech is very good, often close to human.', 'None, as the Monkey Boy Soldier', '30% are minor psionics and 10% are major; roughly the same as humans', '3-4 feet (0.9 to 1.2 m) unaltered, 5-6 feet (1.5 to 1.8 m) with genetic alteration (the Soldier entry''s chimpanzee figures)', '70-90 pounds (31.7 to 40.8 kg), typically doubled for a genetically altered ape (the Soldier entry''s chimpanzee figures)', 'Estimated 40-55 years (the Soldier entry''s figure)', 'The secret level of the GED facility at Lone Star, where 40 of them work for Doctor Bradford', 'Doctor Bradford, by choice rather than by any implant', 'The Coalition authorities, who keep no record of them and would not allow them', 'A full R.C.C. with its own skills; genetically enhanced chimpanzees only. No O.C.C. is offered in the Tech entry itself. A runaway or free-born could learn any pilot, wilderness or rogue skill, but none has ever escaped and 95% do not want to. In place of a kit it has full use of Bradford''s hidden laboratory.', 'A chimpanzee with boosted intellect, taught to read and trained as a scientist, medic or engineer, which the Coalition forbids for any mutant animal. They are an illegal, unrecorded staff of free-thinking researchers who work for Bradford willingly.', 'Rifts World Book 13: Lone Star p.85'),
('mutant-rat', 'Mutant Rat', 'mutant', 'rifts', 1, 'Any, but Anarchist (30%), Miscreant (30%) and Diabolic (30%) are the most common', '{"IQ":"2D6+6","ME":"2D6","MA":"2D6","PS":"3D6","PP":"2D6+8","PE":"3D6","PB":"2D6","Spd":"4D6+6"}', 'PE+1D6', 'PE+4D6', NULL, '3D6', NULL, 'Hit Points are the P.E. number plus 1D6 per level of experience (the formula is level one). S.D.C. is the P.E. number plus 4D6, plus any from physical skills. P.P.E. 3D6 is the permanent base left after psychic development. I.S.P. is NOT printed, although a quarter of the race is psionic. Spd is running; cut it by 30% when climbing. Armor Rating: not applicable.', NULL, NULL, '{"initiative":3,"dodge":1,"roll":2,"pull_punch":1}', '+1 attack per melee round on top of the Hand to Hand skill; all bonuses are in addition to skill bonuses. Combat by Hand to Hand: Assassin.', 'Natural: Climb 85%/80%, Swim 75%, Prowl 60% +2% per level, identify scents 44% +2% per level, track by scent 40% +2% per level. R.C.C. skills: speaks American at 90%, Radio: Basic (+10%), Escape Artist (+20%), Intelligence (+10%), Pick Locks (+10%), Pick Pockets (+10%), Land Navigation (+20%), Wilderness Survival (+10%), Sniper, W.P. Knife (Vibro-Blade), W.P. Energy Rifle, one W.P. of choice, Hand to Hand: Assassin. Four other skills, plus one at levels 3, 6, 9 and 12; six secondary skills, plus two at levels 2, 4, 8 and 12. In CS service never taught to read.', 'Jumps 6 feet (1.8 m) high and 10 feet (3 m) across, 30% farther lengthwise off a run or a swing. Double jointed and ambidextrous. Its tail cannot grip. It has to gnaw wood, concrete or metal to keep its teeth worn down. Speech is usually complete though guttural.', 'None; the race has no interest in studying it, though it likes magic items and weapons', '01-25%: minor psionic with four powers from the sensitive category. Otherwise none', '5 feet (1.5 m)', '120-160 pounds (54 to 72 kg)', 'Estimated 20-30 years; fully grown within one year', 'A few hundred sterilized survivors serve in CS special units; about 313 escapees live in the sewers and lower levels of the Lone Star Complex, and roughly 3200 in the Pecos Badlands', 'Other mutant rats, loosely, in Rat Packs; no one else reliably', 'The Coalition, whose Dog Packs, mutant felines, SAMAS and troops kill them on sight; mutant bats; bandits and Psi-Stalkers of the Pecos', 'A full R.C.C. with its own skills. A free-born rat may instead take an O.C.C. of its choice from the men of arms or adventurer groups, with half the usual number of other skills; escapees can pick up new secondary skills. A character outside CS service is a deserter or a free-born, hunted either way. Kit is DPM riot armor (never an environmental suit), a C-12 laser rifle and two Vibro weapons (knives, claws or one of each); pay is 50-70 credits a month. No cybernetics. Rank stops at Sergeant.', 'A wiry, upright rat with an animal''s head, clawed human-like hands and a long bare tail, bred to be a fast-growing swarm army. The rats saw what they were meant for, turned on their makers and deserted in numbers, and the Coalition has since abandoned the project and ordered them destroyed.', 'Rifts World Book 13: Lone Star p.85-88'),
('mutant-bat', 'Mutant Bat', 'mutant', 'rifts', 1, 'Any, but most are Scrupulous (30%) and Unprincipled (30%)', '{"IQ":"2D6+4","ME":"2D6","MA":"3D6","PS":"3D6","PP":"2D6+9","PE":"3D6","PB":"2D6","Spd":"2D6"}', 'PE+1D6', 'PE+3D6', NULL, '3D6', NULL, 'Hit Points are the P.E. number plus 1D6 per level of experience (the formula is level one). S.D.C. is the P.E. number plus 3D6, plus any from physical skills. Spd 2D6 is on the ground or climbing; flying speed is 6D6+6. Armor Rating: not applicable.', NULL, NULL, '{"initiative":3,"roll":3}', '+1 attack per melee round on top of the Hand to Hand skill. +3 to dodge only while flying; no dodge bonus when grounded. All in addition to skill bonuses. Combat by Hand to Hand: Basic; no other style is available.', 'Natural: Climb 75%/70%, Prowl 50% +2% per level, identify scents 46% +2% per level, track by scent 42% +2% per level. R.C.C. skills: speaks American at 80%, Sing (+15%), Radio: Basic (+20%), Surveillance Systems (+10%), Intelligence (+10%), Detect Ambush (+10%), Detect Concealment (+10%), Land Navigation (+20%), Wilderness Survival (+10%), W.P. Knife (Vibro-Blade), W.P. Energy Rifle, one W.P. of choice, Hand to Hand: Basic. Four other skills, plus one at levels 3, 6, 9 and 12; four secondary skills, plus two at levels 2, 4, 8 and 12. In CS service never taught to read.', 'Flies silently but slowly on its own wings. Echolocation lets it picture its surroundings with no light at all, though high-tech opponents can pick the signal up. Hearing works like the Battle Cat''s with a further +10% to pinpoint, identify and follow sounds. Daylight sight is poor, about 40 ft (12.2 m) unless it wears sunglasses. Tiny tail, double jointed, ambidextrous. Speech is usually partial and guttural.', 'None', 'None', '5 feet (1.5 m), with a wingspan of 10-15 feet (3 to 4.6 m)', '100-120 pounds (the book prints the metric as 45 to 72 kg)', 'Estimated 20-30 years', 'About 240 serve the Coalition military: night reconnaissance over the Pecos Badlands and guard duty at Lone Star City and the Lone Star Complex', 'The Coalition States; gets on well with Dog Boys and mutant felines', 'Mutant rats; the Simvan and bandits of the Pecos Badlands. A bat that deserts is hunted down by the Coalition', 'A full R.C.C. with its own skills; no O.C.C. is offered. A character outside CS service is a deserter or the free-born offspring of runaways. Kit is DPM riot armor (never an environmental suit), a net, a Vibro-Blade of choice, six hand grenades, three smoke grenades and either the C-12 rifle or the C-14 Fire Breather; pay is 70-100 credits a month. Trusted as Dog Boys are. No cybernetics. Rank stops at Lieutenant.', 'A man-sized bat with a bat''s head and huge membrane wings that carry its hands; it waddles hunched over on the ground and climbs on all fours. Loyal and friendly, it proved too slow and too easy to detect to be a useful night spy, and the program was closed, though those already serving are kept on.', 'Rifts World Book 13: Lone Star p.88-89');
